import type { ReactNode } from "react";
import { PLANS, ROLE_SHORTCUT_LIMITS } from "@/lib/plans";
import { cn } from "@/lib/utils";
import { CardSpotlight } from "./card-spotlight";

export const upgradeContexts = {
  allowance: "Get higher daily and monthly sending limits with Premium",
  roles: "Role editing is a Premium feature",
  reminders: "Follow-up reminders are a Premium feature",
  replied: "“Mark replied” is a Premium feature",
  csv: "CSV import is a Premium feature",
  templates: "More than one saved template is a Premium feature",
  shortlist: "Add to shortlist from History is a Premium feature",
  themes: "Chalk and Obsidian themes are Premium features",
  "role-shortcuts": "More than two role shortcuts is a Premium feature",
  highlights: "Custom preview highlight colors are a Premium feature",
  repeat: "Manual repeat sends are a Premium feature",
} as const;
export type UpgradeFeature = keyof typeof upgradeContexts;
const freeFeatures = [
  `${PLANS.FREE.savedTemplates} editable template`,
  `${ROLE_SHORTCUT_LIMITS.free} saved role shortcuts`,
  "PDF attachment, 5 MB",
  "Gmail acceptance status",
  "Lavender & Nightbloom themes",
];
const premiumFeatures: { text: string; keys?: UpgradeFeature[] }[] = [
  { text: "Edit recipient roles in Compose", keys: ["roles"] },
  { text: "Follow-up reminders: 3, 7 or 14 days", keys: ["reminders"] },
  { text: "“Mark replied” tracking", keys: ["replied"] },
  { text: "CSV import, up to 1,000 rows", keys: ["csv"] },
  {
    text: `Unlimited templates & ${ROLE_SHORTCUT_LIMITS.premium} role shortcuts`,
    keys: ["templates", "role-shortcuts"],
  },
  { text: "Add to shortlist directly from History", keys: ["shortlist"] },
  { text: "Manual repeat sends", keys: ["repeat"] },
  { text: "All four themes, including Chalk & Obsidian", keys: ["themes"] },
  { text: "10 preview highlight colors", keys: ["highlights"] },
  { text: "Prioritized email support" },
];

function Stats({
  premium = false,
  compactMobile = false,
}: {
  premium?: boolean;
  compactMobile?: boolean;
}) {
  const limits = premium ? PLANS.PAID : PLANS.FREE;
  return (
    <dl className="pricing-stats m-0 grid grid-cols-3 gap-3">
      {[
        [limits.monthlyEmails, "emails / month"],
        [limits.dailyEmails, "per UTC day"],
        [limits.campaignRecipients, "per campaign"],
      ].map(([value, label]) => (
        <div
          key={label}
          data-upgrade-stat
          className={cn(
            "relative rounded-[18px] bg-upgrade-app px-1.5 py-4 text-center ring-1 ring-upgrade-border transition-[translate,scale,box-shadow] duration-300 ease-[cubic-bezier(0.22,1,0.36,1)] hover:pointer-fine:z-10 hover:pointer-fine:ring-upgrade-ok hover:pointer-fine:shadow-[0_8px_20px_-6px_var(--upgrade-glow),inset_0_0_0_1px_var(--upgrade-ok)] motion-safe:hover:pointer-fine:-translate-y-1 motion-safe:hover:pointer-fine:scale-[1.03] motion-reduce:transition-none",
            compactMobile && "max-[699px]:py-2.5",
          )}
        >
          <dt
            className={cn(
              "block text-[clamp(22px,2.5vw,32px)] leading-none font-bold",
              premium &&
                "bg-[image:var(--upgrade-stat-gradient)] bg-clip-text text-transparent",
            )}
          >
            {value}
          </dt>
          <dd className="m-0 mt-2 block text-[13px] leading-tight text-[var(--upgrade-stat-label)]">
            {label}
          </dd>
        </div>
      ))}
    </dl>
  );
}

export function PlanCard({
  premium = false,
  compactMobile = false,
  price,
  heading: Heading = "h3",
  headingId,
  current = false,
  feature,
  action,
  className,
}: {
  premium?: boolean;
  compactMobile?: boolean;
  price: { symbol: string; amount: number };
  heading?: "h2" | "h3";
  headingId?: string;
  current?: boolean;
  feature?: UpgradeFeature;
  action?: ReactNode;
  className?: string;
}) {
  return (
    <CardSpotlight
      aria-label={premium ? "Premium plan" : "Free plan"}
      className={cn(
        "upgrade-card isolate relative flex min-w-0 flex-col gap-5 overflow-hidden rounded-[34px] border-2 border-upgrade-border p-8 text-upgrade-text max-[699px]:rounded-[26px] max-[699px]:p-6",
        premium &&
          "upgrade-card-premium -order-1 border-2 border-transparent shadow-upgrade-card min-[700px]:order-0",
        compactMobile && "max-[699px]:gap-3 max-[699px]:px-5 max-[699px]:py-5",
        className,
      )}
    >
      <div aria-hidden="true" className="upgrade-spotlight" />
      <div
        className={
          compactMobile
            ? "contents max-[699px]:flex max-[699px]:flex-row-reverse max-[699px]:items-center max-[699px]:justify-between max-[699px]:gap-2"
            : "contents"
        }
      >
        <span
          data-plan-badge
          data-recommended-ribbon={premium || undefined}
          data-recommended-badge={premium || undefined}
          className={cn(
            "self-start rounded-full px-4 py-2 text-[13px] font-semibold uppercase tracking-wide",
            compactMobile &&
              "max-[699px]:self-auto max-[699px]:px-2.5 max-[699px]:py-1.5 max-[699px]:text-[11px]",
            premium && !current
              ? "bg-upgrade-gradient text-upgrade-btn-fg"
              : "bg-upgrade-okbg text-upgrade-muted",
          )}
        >
          {current ? "Current plan" : premium ? "★ Recommended" : "Free plan"}
        </span>
        <Heading id={headingId} className="m-0 text-[22px] font-semibold">
          {premium ? "Premium" : "Free"}
        </Heading>
      </div>
      <p className="m-0 flex flex-wrap items-baseline gap-x-2 gap-y-1 text-[clamp(42px,5vw,64px)] font-extrabold leading-none tracking-tight">
        <span data-localized-price={premium || undefined}>
          {price.symbol}
          {premium ? price.amount : 0}
        </span>{" "}
        <small
          aria-label={premium ? "per month, tax included" : undefined}
          className="text-base font-medium tracking-normal text-upgrade-muted"
        >
          {premium ? "/ month · tax included" : "no card needed"}
        </small>
      </p>
      <Stats premium={premium} compactMobile={compactMobile} />
      {premium && (
        <p className="m-0 text-[12px] uppercase tracking-[0.06em] text-upgrade-muted">
          Everything in Free, plus
        </p>
      )}
      <ul
        className={cn(
          "upgrade-features m-0 flex list-none flex-col gap-3 p-0 text-[15px]",
          compactMobile && "max-[699px]:gap-1.5",
        )}
      >
        {(premium
          ? premiumFeatures
          : freeFeatures.map((text) => ({ text, keys: undefined }))
        ).map(({ text, keys }) => {
          const highlighted = feature !== undefined && keys?.includes(feature);
          return (
            <li
              key={text}
              data-upgrade-feature={keys?.join(" ")}
              data-highlighted={highlighted ? "true" : undefined}
              className={cn(
                "relative leading-[1.35]",
                premium ? "rounded-[10px] py-1.25 pl-9 pr-1.75" : "pl-9",
                compactMobile && "max-[699px]:min-h-6 max-[699px]:py-1",
                highlighted &&
                  "bg-upgrade-okbg font-semibold shadow-[inset_0_0_0_1px_var(--upgrade-ok)]",
              )}
            >
              {text}
            </li>
          );
        })}
      </ul>
      {action}
    </CardSpotlight>
  );
}
